"use client"

import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import {
  Sidebar,
  SidebarContent,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarMenu,
  SidebarMenuAction,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@/components/ui/sidebar"
import { useChatStore } from "@/features/chat/store/chat-store"
import { cn } from "@/lib/utils"
import { useRouter, useSearchParams } from "next/navigation"
import { useState, useTransition } from "react"
import { deleteResponse } from "../actions/responses"
import { SavedResponseMeta } from "../services/chat-history-service"

interface ChatHistorySidebarProps {
  responses: SavedResponseMeta[]
}

export function ChatHistorySidebar({ responses }: ChatHistorySidebarProps) {
  const router = useRouter()
  const searchParams = useSearchParams()
  const currentId = searchParams.get("responseId")
  const [isPending, startTransition] = useTransition()
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [idToDeleteConfirm, setIdToDeleteConfirm] = useState<string | null>(
    null
  )

  const { state, toggleSidebar } = useSidebar()
  const resetChatStore = useChatStore((s) => s.resetAll)
  const isCollapsed = state === "collapsed"

  const handleSelect = (id: string) => {
    const params = new URLSearchParams(searchParams.toString())
    params.set("responseId", id)
    router.push(`/chat?${params.toString()}`)
  }

  const handleNewChat = () => {
    resetChatStore()
    router.push("/chat")
  }

  const confirmDelete = () => {
    if (!idToDeleteConfirm) return

    const id = idToDeleteConfirm
    setDeletingId(id)
    setIdToDeleteConfirm(null)

    startTransition(async () => {
      try {
        await deleteResponse(id)
        if (currentId === id) {
          router.push("/chat")
        }
      } catch (error) {
        console.error("Error al eliminar el análisis:", error)
      } finally {
        setDeletingId(null)
      }
    })
  }

  return (
    <>
      <Sidebar
        collapsible="icon"
        className={cn(
          "h-full shrink-0 border-r border-zinc-200/50 bg-zinc-50/50 transition-all duration-300 dark:border-zinc-800/50 dark:bg-zinc-950/20",
          isCollapsed ? "w-12" : "w-full md:w-80"
        )}
      >
        {/* Cabecera del Sidebar */}
        <SidebarHeader
          className={cn(
            "border-b border-zinc-200/50 dark:border-zinc-800/50",
            isCollapsed ? "p-2" : "px-3 py-3"
          )}
        >
          <div
            className={cn(
              "flex items-center gap-2",
              isCollapsed ? "flex-col justify-center" : "justify-between"
            )}
          >
            {!isCollapsed && (
              <div className="flex animate-in items-center gap-2 text-sm font-semibold duration-200 fade-in">
                <span className="icon-[lucide--history] size-4 text-primary" />
                <span>Historial</span>
              </div>
            )}

            <div
              className={cn(
                "flex items-center gap-1.5",
                isCollapsed && "flex-col"
              )}
            >
              {/* Botón Nuevo Chat */}
              <button
                onClick={handleNewChat}
                title="Nuevo análisis"
                className={cn(
                  "inline-flex items-center justify-center gap-1 rounded-lg bg-primary/10 text-primary transition-colors hover:bg-primary/20",
                  isCollapsed ? "size-8" : "px-2.5 py-1.5 text-xs font-medium"
                )}
              >
                <span className="icon-[lucide--plus] size-4" />
                {!isCollapsed && <span>Nuevo</span>}
              </button>

              {/* Botón de Colapso/Expansión */}
              <button
                onClick={toggleSidebar}
                title={
                  isCollapsed ? "Expandir historial" : "Colapsar historial"
                }
                aria-label={
                  isCollapsed ? "Expandir historial" : "Colapsar historial"
                }
                className="inline-flex size-8 items-center justify-center rounded-lg text-muted-foreground transition-colors hover:bg-muted hover:text-foreground"
              >
                <span
                  className={cn(
                    isCollapsed
                      ? "icon-[lucide--panel-left-open]"
                      : "icon-[lucide--panel-left-close]",
                    "size-4 transition-transform duration-200"
                  )}
                />
              </button>
            </div>
          </div>
        </SidebarHeader>

        {/* Contenido / Listado de Chats */}
        {!isCollapsed && (
          <SidebarContent className="animate-in p-2 duration-200 fade-in">
            <SidebarGroup>
              <SidebarGroupContent>
                {responses.length === 0 ? (
                  <div className="flex flex-col items-center justify-center py-12 text-center text-xs text-muted-foreground">
                    <span className="icon-[lucide--archive-x] mb-2 size-8 opacity-40" />
                    <span>No hay análisis guardados</span>
                  </div>
                ) : (
                  <SidebarMenu className="gap-1.5">
                    {responses.map((resp) => {
                      const isActive = currentId === resp.id
                      const isDeleting = deletingId === resp.id
                      const date = new Date(resp.createdAt).toLocaleDateString(
                        "es-AR",
                        {
                          day: "2-digit",
                          month: "short",
                        }
                      )

                      return (
                        <SidebarMenuItem
                          key={resp.id}
                          className="relative group/menu-item"
                        >
                          <SidebarMenuButton
                            isActive={isActive}
                            className={cn(
                              "h-auto w-full cursor-pointer rounded-lg border text-left transition-colors hover:bg-muted/50",
                              isActive
                                ? "border-primary/30 bg-muted"
                                : "border-zinc-200/40 bg-background/50 dark:border-zinc-800/40"
                            )}
                            render={
                              <button
                                onClick={() => handleSelect(resp.id)}
                                className="flex flex-col items-start gap-1 p-3 pr-9"
                                disabled={isDeleting}
                              >
                                <span className="line-clamp-2 w-full text-xs font-medium text-foreground">
                                  {resp.title}
                                </span>
                                <div className="flex items-center gap-1.5 text-[10px] text-muted-foreground">
                                  <span className="icon-[lucide--calendar] size-3" />
                                  <span suppressHydrationWarning>{date}</span>
                                </div>
                              </button>
                            }
                          />

                          <SidebarMenuAction
                            onClick={(e) => {
                              e.stopPropagation()
                              setIdToDeleteConfirm(resp.id)
                            }}
                            disabled={isPending || isDeleting}
                            showOnHover
                            className="size-7 rounded-md flex items-center justify-center hover:bg-destructive/10 hover:text-destructive disabled:opacity-50 transition-colors"
                          >
                            {isDeleting ? (
                              <span className="icon-[lucide--loader-2] size-3.5 animate-spin" />
                            ) : (
                              <span className="icon-[lucide--trash-2] size-3.5" />
                            )}
                            <span className="sr-only">Eliminar análisis</span>
                          </SidebarMenuAction>
                        </SidebarMenuItem>
                      )
                    })}
                  </SidebarMenu>
                )}
              </SidebarGroupContent>
            </SidebarGroup>
          </SidebarContent>
        )}
      </Sidebar>

      {/* Alerta de confirmación para eliminar */}
      <AlertDialog
        open={idToDeleteConfirm !== null}
        onOpenChange={(open) => !open && setIdToDeleteConfirm(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>¿Confirmas la eliminación?</AlertDialogTitle>
            <AlertDialogDescription>
              Esta acción no se puede deshacer. Se eliminará permanentemente el
              historial seleccionado.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancelar</AlertDialogCancel>
            <AlertDialogAction
              onClick={confirmDelete}
              className="bg-destructive hover:bg-destructive/90 text-destructive-foreground"
            >
              Confirmar
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

</file>
